 if(SUN_DIRECTION.x*sunDirTmp[0]+SUN_DIRECTION.y*sunDirTmp[1]+SUN_DIRECTION.z*sunDirTmp[2]<.99999)SUN_DIRECTION.set(sunDirTmp[0],sunDirTmp[1],sunDirTmp[2]).normalize();
