  const a=rnd()*Math.PI*2,r=rnd()*W*.28,x=Math.cos(a)*r,z=Math.sin(a)*r,h=H*(.55+rnd()*.5),w=Math.max(.035,W*.05),lean=(rnd()-.5)*W*.5,ra=rnd()*Math.PI,cx=Math.cos(ra),cz=Math.sin(ra),ld=rnd()<.5?-1:1;
