  const rows=[[x-cx*w,b.min.y,z-cz*w,x+cx*w,b.min.y,z+cz*w],[x+cz*lean*.35*ld-cx*w*.8,b.min.y+h*.5,z-cx*lean*.35*ld-cz*w*.8,x+cz*lean*.35*ld+cx*w*.8,b.min.y+h*.5,z-cx*lean*.35*ld+cz*w*.8]];
