if(ascVoidEdge&&ascFallFrom===null)ascFallFrom=player.position.y;
const ascVoidFall=!!(ascKey&&ascFallFrom!==null);
let floorY=caveWalk?player.position.y:terrainHeightAt(player.position.x,player.position.z);
