// As colisões das casas passam a ser registradas pelo módulo da cidade de Eldória.
// Os adereços novos registram a própria colisão; os moradores continuam nas coordenadas originais.
function buildAct1Props(){
 if(act1Props)return act1Props;act1Props={kit:null,poses:null,flies:null,door:null,victims:[],kids:[]};
 const L=new GLTFLoader();
 // Substitui a cidade antiga por GLBs autorais de Eldória, sem mover vendedores,
 // moradores ou pontos de missão. O roteiro v1 permanece documento de produção.
 const eldoriaCity=mountEldoriaLiveVillage({
   THREE,GLTFLoader,group:villageGroup,groundHeightAt,center:VILLAGE_CENTER,
   obstacles:marketObstacles,lowSpec:terrainLowSpec,mergeStatic:mergeGroupMeshes
 });
 act1Props.eldoria=eldoriaCity;
 /* MOD 291 — marco 3: cidade bonita e íntegra (o Bispo levou o dinheiro, não as casas): deques e escadas nas árvores
    ancestrais, a passarela suspensa do criador entre duas delas, canteiros, sebes, cercas claras e lampiões. */
 act1Props.dressing=mountCityDressing(THREE,GLTFLoader,{group:villageGroup,groundHeightAt,center:VILLAGE_CENTER,plots:ELDORIA_PLOTS,lowSpec:terrainLowSpec,obstacles:marketObstacles,
  structures:treeStructurePlan(VILLAGE_CENTER),walk:eldoriaWalk,fetchModel:eldoriaCity.fetchModel,
  lamps:[], // MOD 316: os 10 postes/lanternas de caixa saíram; a praça usa só as 2 tochas GLB
  isFree:(x,z)=>!trailRoutes.some(r=>closeToPolyline(x,z,r.points,r.width*.5+.5))&&!closeToPolyline(x,z,RIVER_POINTS,RIVER.width+1)&&!marketObstacles.some(o=>Math.hypot(o.x-x,o.z-z)<(o.radius||1)+.4)});
 eldoriaCity.complete.then(report=>{
   window.EldoriaLiveCityQA={loaded:report.loaded,expected:report.expected,failures:report.failures,
     village:{...VILLAGE_CENTER},spawnDistance:+Math.hypot(FALL_SPOT.x-VILLAGE_CENTER.x,FALL_SPOT.z-VILLAGE_CENTER.z).toFixed(1),
     overlaps:report.overlaps,market:marketStalls.map(m=>({label:m.label,x:+m.x.toFixed(1),z:+m.z.toFixed(1)})),well:{x:VILLAGE_CENTER.x-1.4,z:VILLAGE_CENTER.z-.6},fountain:{x:VILLAGE_CENTER.x+ELDORIA_DRY_FOUNTAIN.x,z:VILLAGE_CENTER.z+ELDORIA_DRY_FOUNTAIN.z},grounding:report.grounding,lodDistance:report.lodDistance,lodAudit:report.lodAudit,maxSlope:Math.max(0,...report.grounding.map(g=>g.slope)),lods:report.grounding.filter(g=>g.lod).length};
   if(report.failures.length)console.warn('Eldória: falha de modelos na cidade',report.failures);
 }).catch(error=>console.warn('Eldória: falha de montagem',error));
 buildSewerDoor();
 // Dois personagens infantis Meshy; nunca se instanciam crianças no povoado.
 Promise.all([
  npcFactory.create({sex:'boy',role:'idle',x:CAGE_SPOTS[0].x,z:CAGE_SPOTS[0].z,yaw:Math.PI}),
  npcFactory.create({sex:'girl',role:'idle',x:CAGE_SPOTS[1].x,z:CAGE_SPOTS[1].z,yaw:Math.PI})
 ]).then(children=>{
  children.forEach((c,i)=>{
    c.holder.name=i?'MeninaGaiolaMeshy':'MeninoGaiolaMeshy';
    const cageFloor=cageDoors[i]?.parent?.position.y;
    if(Number.isFinite(cageFloor)){
      // Chão REAL da gaiola; não tratar o telhado/colisor como terreno caminhável.
      c.holder.updateMatrixWorld(true);
      const feet=new THREE.Box3().setFromObject(c.holder).min.y;
      c.holder.position.y+=cageFloor+.075-feet;
    }
    scene.add(c.holder);act1Props.kids.push(c.holder);
    if(c.mixer)villageNpcMixers.push(c.mixer);
  });
  window.SevenSinsChildNpcReport={
    loaded:true,source:ELDORIA_NPC_MODELS.boy,girlSource:ELDORIA_NPC_MODELS.girl,
    childrenInVillage:0,animations:children[0].clips,girlAnimations:children[1].clips,
    cages:children.map((c,i)=>{
      c.holder.updateMatrixWorld(true);
      const b=new THREE.Box3().setFromObject(c.holder);
      return {feetY:+b.min.y.toFixed(3),height:+b.getSize(new THREE.Vector3()).y.toFixed(3),floorY:+(cageDoors[i]?.parent?.position.y||0).toFixed(3)};
    })
  };
  syncAct1World();
 }).catch(e=>console.error('GLBs infantis Meshy indisponíveis; não criar substitutos procedurais',e));
 // Moscas sobre a comida podre e os corpos (uma chamada de desenho).
 // Apenas bancas reais e moradores efetivamente caídos: sem moscas em corpos genéricos removidos.
 const spots=marketStalls.map(s=>({x:s.x,z:s.z,h:.95})).concat(flyNpcTargets.map(n=>({npc:n,h:.4})));
 // Reservar posições para os corpos que carregam de modo assíncrono.
 while(spots.length<marketStalls.length+2)spots.push({npcIndex:spots.length-marketStalls.length,h:.4});
 const N=spots.length*7,pos=new Float32Array(N*3),seed=[];for(let i=0;i<N;i++){const s=spots[i%spots.length];seed.push({s,a:Math.random()*6.28,r:.25+Math.random()*.5,h:.5+Math.random()*.9,v:2+Math.random()*3});}
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(pos,3));
 const flies=new THREE.Points(geo,new THREE.PointsMaterial({color:0x111111,size:.045}));flies.frustumCulled=false;villageGroup.add(flies);
 act1Props.flies={geo,seed};
 return act1Props;
}
function buildSewerDoor(){
 // Entrada do esgoto na encosta: arco de pedra com grade arrombada e escuridão dentro.
 const g=new THREE.Group();g.position.set(SEWER_DOOR.x,groundHeightAt(SEWER_DOOR.x,SEWER_DOOR.z),SEWER_DOOR.z);g.rotation.y=SEWER_DOOR.yaw;scene.add(g);
 const stone=mat(0x55524a),dark=new THREE.MeshBasicMaterial({color:0x020202});
 // Contraforte conectado ao terreno atrás do arco; a entrada não fica solta no campo.
 const ridge=new THREE.Mesh(new THREE.DodecahedronGeometry(1,1),stone);ridge.scale.set(14,13,12);ridge.position.set(0,6,-12);ridge.castShadow=true;g.add(ridge);
 for(const side of [-1,1]){const flank=new THREE.Mesh(new THREE.DodecahedronGeometry(1,1),stone);flank.scale.set(6,7,8);flank.position.set(side*8.5,3,-5);g.add(flank);}
 const backX=SEWER_DOOR.x-Math.sin(SEWER_DOOR.yaw)*12,backZ=SEWER_DOOR.z-Math.cos(SEWER_DOOR.yaw)*12;marketObstacles.push({x:backX,z:backZ,radius:10,height:17});
 const rocks=[];for(let i=0;i<9;i++){const a=(i/8)*Math.PI;rocks.push([Math.cos(a)*2.2,.3+Math.sin(a)*2.3,-.3]);}
 for(const [x,y,z] of rocks){const r=new THREE.Mesh(new THREE.DodecahedronGeometry(.62,0),stone);r.position.set(x,y,z);r.rotation.set(x,y,z);r.castShadow=true;g.add(r);}
 for(let i=0;i<7;i++){const r=new THREE.Mesh(new THREE.DodecahedronGeometry(1.4+Math.random(),0),stone);r.position.set((Math.random()-.5)*7,1+Math.random()*2.4,-1.6-Math.random()*1.5);r.castShadow=true;g.add(r);}
 const hole=new THREE.Mesh(new THREE.CircleGeometry(1.8,20,0,Math.PI),dark);hole.position.set(0,.3,-.2);g.add(hole);
 const holeLow=new THREE.Mesh(new THREE.PlaneGeometry(3.6,.32),dark);holeLow.position.set(0,.16,-.2);g.add(holeLow);
 const iron=mat(0x2a2622);for(let i=0;i<5;i++){const bar=new THREE.Mesh(new THREE.CylinderGeometry(.04,.04,2.2,5),iron);bar.position.set(-1.6+i*.35,.35,.6+i*.08);bar.rotation.set(1.35,0,.25*i);g.add(bar);}
 act1Props.door=g;marketObstacles.push({x:SEWER_DOOR.x-Math.sin(SEWER_DOOR.yaw)*1.8,z:SEWER_DOOR.z-Math.cos(SEWER_DOOR.yaw)*1.8,radius:2.2,height:3});
 syncAct1World();
}
function sewerDoorFront(){return{x:SEWER_DOOR.x+Math.sin(SEWER_DOOR.yaw)*1.4,z:SEWER_DOOR.z+Math.cos(SEWER_DOOR.yaw)*1.4};}
/** Mostra/esconde o que depende da etapa (crianças, entrada do esgoto, portal antigo da montanha). */
function syncAct1World(){
 if(!act1Props)return;
 for(const k of act1Props.kids)k.visible=(questStep===2||(questStep===3&&act1Sub===0))&&!childrenFreed;
 if(act1Props.door)act1Props.door.visible=questStep>=4&&questStep<8;
 portalGroup.visible=questStep>=8;portalBeacon.visible=false;
}
function updateFlies(now){const f=act1Props&&act1Props.flies;if(!f||Math.hypot(player.position.x-VILLAGE_CENTER.x,player.position.z-VILLAGE_CENTER.z)>40)return;const t=now*.001,a=f.geo.attributes.position;
 for(let i=0;i<f.seed.length;i++){const s=f.seed[i],ang=s.a+t*s.v;const npc=s.s.npc||((s.s.npcIndex!==undefined)?flyNpcTargets[s.s.npcIndex]:null);
  const x=npc?npc.position.x:s.s.x,z=npc?npc.position.z:s.s.z;
  if(!Number.isFinite(x)||!Number.isFinite(z)){a.array[i*3+1]=-999;continue;}
  a.array[i*3]=x+Math.cos(ang)*s.r;
  a.array[i*3+1]=groundHeightAt(x,z)+s.h+Math.sin(t*7+i)*.08;
  a.array[i*3+2]=z+Math.sin(ang*1.3)*s.r;}a.needsUpdate=true;}
