/* MOD 219 — entrar na caverna a pé: o herói anda até a boca e some no escuro do túnel; a tela escurece e ele
   aparece lá dentro, com a luz da entrada às costas. */
var caveWalk=null;
function caveWalkIn(cb){if(caveWalk)return;const C=SC.cave,yaw=(act3World&&act3World.caveYaw)||0,P=player.position,to={x:C.x+Math.sin(yaw)*-2.4,z:C.z+Math.cos(yaw)*-2.4};
 caveWalk={t:0,from:{x:P.x,z:P.z,y:P.y},to,y:(act3World&&act3World.caveY)||P.y,cb};act1Lock=true;moveVX=moveVZ=0;faceTo(player,to);if(actions.walk)play('walk',.2);worldAudio.whoosh&&worldAudio.whoosh();
 const veil=document.getElementById('travel-veil');setTimeout(()=>{if(veil)veil.classList.add('on');},900);
 setTimeout(()=>{const w=caveWalk;caveWalk=null;act1Lock=false;w.cb();if(actions.idle)play('idle',.2);setTimeout(()=>{if(veil)veil.classList.remove('on');},350);},1450);}
function updateCaveWalk(dt){if(!caveWalk)return;const w=caveWalk;w.t+=dt;const k=Math.min(1,w.t/1.4);player.position.x=w.from.x+(w.to.x-w.from.x)*k;player.position.z=w.from.z+(w.to.z-w.from.z)*k;player.position.y=w.from.y+(w.y-w.from.y)*k;}
function travelVeil(cb){const veil=document.getElementById('travel-veil');if(veil)veil.classList.add('on');setTimeout(()=>{cb();setTimeout(()=>{if(veil)veil.classList.remove('on');},180);},520);}
/* MOD 311 — caverna da fronteira → portal-vórtice → escadaria → ilha do deserto negro.
   Zonas internas no padrão das dimensões (voidSpec), com piso/teto/câmera vindos das mesmas funções da malha.
   Transições: o túnel escurece conforme o herói avança (sem botão de teletransporte); o portal só leva quem
   ATRAVESSA o plano do disco no sentido certo, com tempo de recarga na volta. Cenas montadas antes (pré-carga)
   e shaders compilados de forma assíncrona para não travar no meio da passagem. */
const ascZones={},ascVeil=(()=>{const d=document.createElement('div');d.id='ascensao-escuro';d.style.cssText='position:fixed;inset:0;background:#000;opacity:0;pointer-events:none;z-index:40;transition:opacity .45s ease';document.body.appendChild(d);return d;})();
let ascKey=null,ascBusy=false,ascCooldownUntil=0,ascPrev={x:0,z:0},ascPreload=null,ascFallFrom=null;
const ascBuilders={cave:()=>buildCave(THREE,{GLTFLoader,prepareBaked:r=>clampBakedMips(THREE,r,terrainLowSpec?4:3.5),lowSpec:terrainLowSpec,origin:ASC_ZONES.cave}),ascent:()=>buildAscent(THREE,{GLTFLoader,prepareBaked:r=>clampBakedMips(THREE,r,terrainLowSpec?4:3.5),lowSpec:terrainLowSpec,origin:ASC_ZONES.ascent})};
function ascZone(key){if(!ascZones[key]){const z=ascBuilders[key]();scene.add(z.group);z.warm=z.ready.then(()=>{z.group.visible=true;const c=renderer.compileAsync?renderer.compileAsync(z.group,camera,scene):Promise.resolve();return Promise.race([c,new Promise(r=>setTimeout(r,2500))]).catch(()=>{}).finally(()=>{if(ascKey!==key)z.group.visible=false;});});ascZones[key]=z;}return ascZones[key];}
function ascWhenReady(key){const z=ascZone(key);return Promise.race([z.warm,new Promise(r=>setTimeout(r,6000))]).then(()=>z);}
function ascDarken(on,ms){ascVeil.style.transition='opacity '+((ms||450)/1000)+'s ease';ascVeil.style.opacity=on===true?1:on===false?0:String(on);}
function ascEnter(key,at){
 ascFallFrom=null;
 const z=ascZone(key),O=ASC_ZONES[key];if(ascKey&&ascKey!==key&&ascZones[ascKey])ascZones[ascKey].group.visible=false;
 voidSpec={x:O.x,z:O.z,y:0,radius:1e4,walk:(lx,lz)=>z.walk(lx,lz),floor:z.floor,ceil:z.roof||null,camSolid:z.camSolid,hazard:z.hazard||null,solid:true};
 voidMode=true;dimKey=null;ascKey=key;z.group.visible=true;
 skyDome.visible=false;portalBeacon.visible=false;sunDisk.visible=false;sunHalo.visible=false;if(moonRoot)moonRoot.visible=false;if(starField)starField.visible=false;
 const x=O.x+at.x,zz=O.z+at.z;player.position.set(x,z.floor(at.x,at.z),zz);playerYaw=at.yaw;player.rotation.y=at.yaw;cameraYaw=at.yaw+Math.PI;cameraPitch=.14;moveVX=moveVZ=0;dashRemaining=0;verticalVelocity=0;grounded=true;
 checkpointX=x;checkpointZ=zz;camera.position.set(x-Math.sin(at.yaw)*5.5,player.position.y+2.6,zz-Math.cos(at.yaw)*5.5);ascPrev={x:at.x,z:at.z};ascCooldownUntil=performance.now()+1600;
}
function ascHide(){ascFallFrom=null;if(ascKey&&ascZones[ascKey])ascZones[ascKey].group.visible=false;ascKey=null;}
function ascLeaveToWorld(){
 const M=CAVE_MOUTH,x=M.x-5.5,z=M.z;ascHide();voidSpec.walk=null;leaveVoid();
 player.position.set(x,terrainHeightAt(x,z),z);playerYaw=Math.PI/2;player.rotation.y=playerYaw;cameraYaw=playerYaw+Math.PI;moveVX=moveVZ=0;checkpointX=x;checkpointZ=z;
 camera.position.set(x-6,player.position.y+2.8,z);ascCooldownUntil=performance.now()+1800;ascScheduleUnload();
}
/** Descarrega as zonas (GPU e memória) depois de um tempo longe da boca; voltar remonta tudo com pré-carga. */
let ascUnloadTimer=0;
function ascScheduleUnload(){clearTimeout(ascUnloadTimer);ascUnloadTimer=setTimeout(()=>{const P=player.position;if(ascKey||ascBusy||Math.hypot(P.x-CAVE_MOUTH.x,P.z-CAVE_MOUTH.z)<120){ascScheduleUnload();return;}
 for(const k of Object.keys(ascZones)){const z=ascZones[k];scene.remove(z.group);z.dispose();delete ascZones[k];}ascPreload=null;ascUnloadTimer=0;},45000);}
function ascTravel(fn,{color='#000',hold=260}={}){if(ascBusy)return;ascBusy=true;ascVeil.style.background=color;ascDarken(true,380);
 setTimeout(()=>{Promise.resolve(fn()).catch(e=>console.warn('Ascensão: transição',e)).finally(()=>{setTimeout(()=>{ascDarken(false,620);ascBusy=false;ascVeil.style.background='#000';},hold);});},400);}
function updateAscension(dt,now){
 const P=player.position;
 if(!ascKey){
  if(!voidMode)frontier.update(camera);
  if(voidMode||ascBusy)return;
  const dm=Math.hypot(P.x-CAVE_MOUTH.x,P.z-CAVE_MOUTH.z);
  if(dm<75&&!ascPreload){ascPreload=(window.requestIdleCallback||setTimeout)(()=>{ascZone('cave');});}
  else if(dm>150&&ascPreload&&!ascUnloadTimer)ascScheduleUnload();
  if(inMouthTunnel(P.x,P.z)){const d=mouthDepth(P.x);ascDarken(Math.max(0,Math.min(.92,(d-.18)/(CAVE_MOUTH.enterDepth-.18)*.92)),180);
   if(d>=CAVE_MOUTH.enterDepth&&P.x<ascPrev.x-1e-4&&now>ascCooldownUntil)ascTravel(()=>ascWhenReady('cave').then(()=>{const S=ASC_CAVE.spawn;ascEnter('cave',S);status.textContent='Caverna da Fronteira — o frio vem lá de dentro.';}));}
  else if(ascVeil.style.opacity!=='0'&&!ascBusy)ascDarken(false,300);
  ascPrev={x:P.x,z:P.z};return;
 }
 const Z=ascZones[ascKey],O=ASC_ZONES[ascKey],lx=P.x-O.x,lz=P.z-O.z,e=Z.env;
 scene.background.setHex(e.bg);scene.fog.color.setHex(e.fog);scene.fog.near=e.fogNear;scene.fog.far=e.fogFar;hemiLight.color.setHex(e.hemi[0]);hemiLight.groundColor.setHex(e.hemi[1]);hemiLight.intensity=e.hemi[2];sunLight.color.setHex(e.sun[0]);sunLight.intensity=e.sun[1];fill.intensity=.2;renderer.toneMappingExposure=e.exposure;dimLight.intensity=0;
 Z.update(dt,camera,{x:lx,y:P.y,z:lz});
 if(!ascBusy&&now>ascCooldownUntil){
  if(ascKey==='cave'){
   if(lz>ASC_CAVE.exitZ&&lz>ascPrev.z)ascTravel(()=>{ascLeaveToWorld();status.textContent='De volta à serra.';});
   else if(crossedCavePortal(ascPrev,{x:lx,z:lz})){Z.portal.pulse();worldAudio.portalEnter();ascTravel(()=>ascWhenReady('ascent').then(()=>{ascEnter('ascent',ASC_ASCENT.spawn);status.textContent='Uma escadaria sem fim sobe pelo vazio.';}),{color:'#1a0c3a',hold:420});}
  }else if(ascKey==='ascent'&&crossedAscentPortal(ascPrev,{x:lx,z:lz})){Z.portal.pulse();worldAudio.portalEnter();ascTravel(()=>ascWhenReady('cave').then(()=>{const p=ASC_CAVE.portal;ascEnter('cave',{x:p.x,z:p.z+4.5,yaw:0});}),{color:'#0a1440',hold:380});}
 }
 ascPrev={x:lx,z:lz};
 // pré-carga da escadaria quando o herói chega à câmara do portal
 if(ascKey==='cave'&&lz<-100&&!ascZones.ascent)(window.requestIdleCallback||setTimeout)(()=>ascZone('ascent'));
}
/* ---------- Etapas ---------- */
function act1Advance(step,sub){questStep=step;act1Sub=sub||0;save3DProgress();updateQuestHud();syncAct1World();}
function act1Toast(text){const toast=document.getElementById('quest-toast');if(!toast)return;toast.textContent=text;toast.classList.remove('hidden');setTimeout(()=>toast.classList.add('hidden'),2600);}
function act1Busy(){return cineActive||dialogueOpen||namePromptOpen||act1Lock||packFinishing||!!portalPull;}
/** Marcador da missão e gatilhos por proximidade. */
function updateAct1(dt,now){
 updatePack(dt);updateFlies(now);updateRoad(dt);
 if(questStep<1||questStep>8)return;
 if(questStep>=3&&questStep<=4&&!rigLoads.enemy2)loadRig('enemy2').catch(()=>{});
 const px=player.position.x,pz=player.position.z,near=(p,r)=>Math.hypot(p.x-px,p.z-pz)<r,mark=p=>questMarker.position.set(p.x,terrainHeightAt(p.x,p.z)+.06,p.z);
 if(!cineActive)guide.visible=questStep===0||questStep>=8||guideFighting;
 roadCompanion(dt);
 if(questStep===1){
  if(act1Sub===0&&roadStage<ROAD.done){updateRoadQuest(px,pz,near,mark);return;}
  if(act1Sub===0){mark(VILLAGE_CENTER);if(!act1Busy()&&near(VILLAGE_CENTER,VILLAGE_CLEAR_RADIUS+2)){act1Lock=true;storyAnchors.village={x:VILLAGE_CENTER.x,z:VILLAGE_CENTER.z,yaw:0};playStory('vila-chegada',villageArrivalScene(),{done:()=>{act1Lock=false;act1Advance(1,1);status.textContent='Pergunte ao vendedor sobre o Pecado da Ganância.';}});}}
  else{const t=villageVendors[1];mark(t);}
  return;
 }
 if(questStep===2){
  mark(CAGE_CENTER);storyAnchors.cage={x:CAGE_CENTER.x,z:CAGE_CENTER.z,yaw:Math.PI};
  if(!act1Busy()&&!pack&&!enemy.visible&&near(CAGE_CENTER,13)){
   act1Lock=true;
   if(journeyEnemyIndex===0){
    const first=JOURNEY_ENEMIES[0];storyAnchors.enemySpot={x:first.x,z:first.z};
    startPack({rig:'enemy1',profile:'captor',hp:100,spots:[first],hold:true,intro:'Um Seguidor da Ganância!',onEach:()=>{journeyEnemyIndex=1;save3DProgress();},onDone:forestSecond});
    playStory('floresta-1',forestFirstScene(),{focus:'enemy',face:'cage',done:()=>{act1Lock=false;packNext();}});
   }else{
    // Retomada (morreu ou recarregou): os que faltam aparecem de uma vez.
    const rest=JOURNEY_ENEMIES.slice(journeyEnemyIndex);if(!rest.length){act1Lock=false;forestCleared();return;}startPack({rig:'enemy1',profile:'captor',hp:100,spots:rest,onEach:()=>{journeyEnemyIndex++;save3DProgress();},onDone:forestCleared});act1Lock=false;
   }
  }
  return;
 }
 if(questStep===3){
  storyAnchors.cage={x:CAGE_CENTER.x,z:CAGE_CENTER.z,yaw:Math.PI};
  if(act1Sub===0)mark(CAGE_CENTER);
  else if(act1Sub===1&&!pack&&!act1Busy()){act1Lock=true;startPack({rig:'enemy1',profile:'captor',hp:110,spots:CAGE_SPOTS.map(s=>({x:s.x,z:s.z+1.2})),onDone:childrenCleared});act1Lock=false;}
  else if(act1Sub===2&&!act1Busy()){act1Lock=true;playFaint();}
  return;
 }
 if(questStep===4){
  if(inSewer){
   const S=SEWER;
   if(act1Sub<=2){mark(sewerLocal(S.feeding));storyAnchors.feeding={...sewerLocal(S.carcass),yaw:0};
    if(!act1Busy()&&!pack&&near(sewerLocal(S.feeding),S.feeding.r+6)){act1Lock=true;
     const prey=sewerLocal(S.carcass);
     startPack({rig:'enemy1',profile:'captor',hp:110,spots:S.feedingSpots.map(sewerLocal),hold:true,intro:'Os Seguidores largam a presa.',cloneOpts:{role:'attack',timeScale:.45},onDone:feedingCleared});
     if(pack)for(const c of pack.clones)if(c)c.lookAt={x:prey.x,z:prey.z};
     playStory('banquete',feedingScene(),{focus:'feeding',done:()=>{act1Lock=false;if(pack){for(const c of pack.clones)if(c)c.lookAt=null;packNext();}}});}}
   else if(act1Sub===3){const h=sewerLocal(S.hole);mark(h);storyAnchors.hole={x:h.x,z:h.z,y:voidSpec.y,yaw:0};if(!act1Busy()&&near(h,6)){act1Lock=true;playHole();}}
  }else{
   if(act1Sub===0){mark(MASSACRE_SPOT);storyAnchors.massacre={x:MASSACRE_SPOT.x,z:MASSACRE_SPOT.z,yaw:0};if(!act1Busy()&&!pack&&near(MASSACRE_SPOT,17)){act1Lock=true;playMassacre();}}
   else{mark(SEWER_DOOR);}
  }
  return;
 }
 if(questStep===5&&inSewer){
  const S=SEWER,w=sewerLocal(S.warden);mark(w);
  if(guideFighting&&sewerZone(px-DIMENSIONS.esgoto.center.x,pz-DIMENSIONS.esgoto.center.z)!=='cell'&&Math.hypot(px-sewerLocal(S.cell).x,pz-sewerLocal(S.cell).z)>16){guideFighting=false;guide.visible=false;for(const c of hordeClones.splice(0))disposeClone(c);}
  if(!act1Busy()&&!pack&&!enemy.visible&&near(w,14)){act1Lock=true;
   const first=!wardenTaunted;startPack({rig:'enemy1',profile:'warden',hp:ACT1.wardenHp,spots:[w],hold:true,scale:1.35,intro:'O Guardião do Portal!',onDone:wardenDown});
   if(first)playStory('guardiao',wardenIntroScene(),{focus:'enemy',done:()=>{act1Lock=false;wardenTaunted=true;save3DProgress();packNext();}});else{act1Lock=false;packNext();}
  }
  return;
 }
 if((questStep===6||questStep===7)&&inSewer){mark(sewerLocal(SEWER.portal));return;}
 if(questStep>=5&&questStep<=7&&!inSewer)mark(SEWER_DOOR);
}
function act1TalkLabel(){
 if(cineActive)return '';const px=player.position.x,pz=player.position.z;
 if(questStep===1&&act1Sub>=1){const t=villageVendors[1];if(Math.hypot(t.x-px,t.z-pz)<=2.9)return 'PERGUNTAR · TÉO';}
 if(questStep===3&&act1Sub===0&&Math.hypot(CAGE_CENTER.x-px,CAGE_CENTER.z-pz)<=4.2)return 'ABRIR GAIOLA';
 if(questStep===4&&act1Sub===1&&!inSewer){const d=sewerDoorFront();if(Math.hypot(d.x-px,d.z-pz)<=3.4)return 'ENTRAR NO ESGOTO';}
 if(questStep>=4&&questStep<8&&!inSewer&&act1Sub>=2||(questStep>=5&&questStep<8&&!inSewer)){const d=sewerDoorFront();if(Math.hypot(d.x-px,d.z-pz)<=3.4)return 'ENTRAR NO ESGOTO';}
 if(inSewer&&(questStep===6||questStep===7)){const p=sewerLocal(SEWER.portal);if(Math.hypot(p.x-px,p.z-pz)<=4.5)return 'ATRAVESSAR';}
 if(inSewer&&!enemy.visible&&!pack){const e=sewerLocal(SEWER.checkpoints.entrance);if(Math.hypot(e.x-px,e.z-pz)<=3)return 'SAIR DO ESGOTO';}
 return '';
}
function act1Interact(){
 const label=act1TalkLabel();if(!label)return false;
 if(label==='PERGUNTAR · TÉO'){faceTo(player,villageVendors[1]);if(coins<ACT1.bribe){playStory('vendedor-recusa',vendorRefusalScene(),{focus:'vendor',face:'vendor'});return true;}
  playStory('vendedor',vendorScene(),{focus:'vendor',face:'vendor',done:skipped=>{if(skipped&&!act1Night)nightFalls(true);act1Advance(2,0);journeyEnemyIndex=0;save3DProgress();status.textContent='Vá à floresta e investigue o choro das crianças.';}});return true;}
 if(label==='ABRIR GAIOLA'){faceTo(player,CAGE_CENTER);openCage();return true;}
 if(label==='ENTRAR NO ESGOTO'){travelVeil(()=>{if(questStep===4&&act1Sub===1)act1Advance(4,2);enterSewer();});return true;}
 if(label==='SAIR DO ESGOTO'){travelVeil(()=>leaveSewer());return true;}
 if(label==='ATRAVESSAR'){openVhazraelPortal();return true;}
 return false;
}
function nightFalls(instant){act1Night=true;if(instant){setGameHour(21.5);return;}setCineFade(1,1.1,false);setTimeout(()=>{setGameHour(21.5);storyTitle('MAIS TARDE','A floresta à noite');setCineFade(0,1.6,false);},1250);}
/* ---------- MOD 291 — Missão P1: a estrada de Teren (prologue-road-flow.js) ----------
   A carroça anda de verdade pela estrada (curva da rota, inclinação pelo relevo); o herói e o Anjo viajam dentro dela.
   Cochilo → noite → quatro bandidos humanos famintos (sem magia) → escolha de expressão → time-lapse até o amanhecer
   → chegada a Eldória. Nada aqui altera chefes, habilidades ou a dimensão de VHAZRAEL. */
var roadStage=ROAD.done;
try{roadStage=initialRoadStage(questStep,localStorage.getItem(ROAD_STORE),act1Sub);}catch(_){roadStage=initialRoadStage(questStep,null,act1Sub);}
function setRoadStage(v){roadStage=v;try{localStorage.setItem(ROAD_STORE,String(v));}catch(_){}updateQuestHud();}
const roadCurve=new THREE.CatmullRomCurve3(CART_ROUTE.map(p=>new THREE.Vector3(p[0],0,p[1])),false,'centripetal');
var prologueAwake=null,originWarned=0;
const road={arrived:false,approach:false,group:null,cart:null,cartModel:null,mule:null,legs:[],teren:null,tarp:null,s:RIDE.start,speed:0,ride:false,yaw:null,legT:0,met:false,bandits:[],choice:null,dawnK:-1,obstacle:null,passengers:false,leaving:0};
Object.assign(SPEAKER_ACTOR,{[ROAD_SPEAKERS.teren]:'teren',[ROAD_SPEAKERS.chief]:'bandit',[ROAD_SPEAKERS.bandit]:'bandit'});
Object.assign(STORY_EYE,{teren:1.55,bandit:1.5,cart:1.6});
const _rp=new THREE.Vector3(),_rt=new THREE.Vector3();
function roadAt(s){const u=THREE.MathUtils.clamp(s/RIDE.total,0,1);roadCurve.getPointAt(u,_rp);roadCurve.getTangentAt(u,_rt);return{x:_rp.x,z:_rp.z,yaw:Math.atan2(_rt.x,_rt.z)};}
/** Mula procedural (sem asset de terceiros): corpo, pescoço, cabeça, orelhas, quatro pernas articuladas e cauda. */
function buildMule(){
 const g=new THREE.Group(),hide=mat(0x6a4a31),dark=mat(0x2e2219),light=mat(0x9a7a5a);
 const body=new THREE.Mesh(new THREE.CapsuleGeometry(.36,.95,6,12),hide);body.rotation.x=Math.PI/2;body.position.set(0,1.12,0);g.add(body);
 const neck=new THREE.Mesh(new THREE.CylinderGeometry(.15,.24,.78,10),hide);neck.position.set(0,1.46,.66);neck.rotation.x=.72;g.add(neck);
 const head=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.42,4,10),hide);head.position.set(0,1.66,1.02);head.rotation.x=1.95;g.add(head);
 const muzzle=new THREE.Mesh(new THREE.SphereGeometry(.13,10,8),light);muzzle.scale.set(1,.8,1.1);muzzle.position.set(0,1.5,1.26);g.add(muzzle);
 for(const sx of [-1,1]){const ear=new THREE.Mesh(new THREE.ConeGeometry(.05,.3,6),hide);ear.position.set(.08*sx,1.95,.9);ear.rotation.set(-.35,0,.25*sx);g.add(ear);}
 const mane=new THREE.Mesh(new THREE.BoxGeometry(.06,.12,.7),dark);mane.position.set(0,1.66,.56);mane.rotation.x=.72;g.add(mane);
 const tail=new THREE.Mesh(new THREE.CylinderGeometry(.025,.05,.6,6),dark);tail.position.set(0,.98,-.78);tail.rotation.x=-.4;g.add(tail);
 road.legs=[];
 for(const [lx,lz,ph] of [[-.2,.42,0],[.2,.42,Math.PI],[-.2,-.42,Math.PI],[.2,-.42,0]]){
  const pivot=new THREE.Group();pivot.position.set(lx,1,lz);const leg=new THREE.Mesh(new THREE.CylinderGeometry(.06,.05,.95,6),hide);leg.position.y=-.48;pivot.add(leg);
  const hoof=new THREE.Mesh(new THREE.CylinderGeometry(.065,.07,.1,6),dark);hoof.position.y=-.95;pivot.add(hoof);g.add(pivot);road.legs.push({pivot,ph});}
 // Varais ligando a mula à carroça.
 for(const sx of [-1,1]){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.03,.03,2.3,5),mat(0x4a3726));pole.rotation.x=Math.PI/2-.08;pole.position.set(.36*sx,1.02,-1.25);g.add(pole);}
 g.traverse(o=>{if(o.isMesh){o.castShadow=!terrainLowSpec;o.receiveShadow=true;}});return g;
}
function ensureRoadProps(){
 if(road.group)return;road.group=new THREE.Group();road.group.name='teren-road-mod291';scene.add(road.group);
 road.cart=new THREE.Group();road.group.add(road.cart);
 road.mule=buildMule();road.group.add(road.mule);
 /* Asset do criador (Cavalo.glb, animado, + ArreiosCavalo.glb) substitui a mula procedural assim que carrega; a mula fica
    só como reserva se o GLB falhar. O cavalo vem em escala ~1e-3: mede pelos ossos (a caixa do SkinnedMesh não serve). */
 new GLTFLoader().load('./Cavalo.glb',gltf=>{const h=gltf.scene,mix=new THREE.AnimationMixer(h),clip=gltf.animations[0];if(clip){road.horseAction=mix.clipAction(clip);road.horseAction.play();}mix.update(.4);h.updateMatrixWorld(true);
  const b=new THREE.Box3(),v=new THREE.Vector3();h.traverse(o=>{if(o.isBone){o.getWorldPosition(v);b.expandByPoint(v);}if(o.isMesh){o.castShadow=!terrainLowSpec;o.receiveShadow=true;o.frustumCulled=false;}});
  if(b.isEmpty())return;const k=1.62/Math.max(1e-9,b.max.y-b.min.y);h.scale.setScalar(k);h.position.set(-(b.min.x+b.max.x)/2*k,-b.min.y*k+.04,-(b.min.z+b.max.z)/2*k);
  const horse=new THREE.Group();horse.add(h);road.horseMixer=mix;
  new GLTFLoader().load('./ArreiosCavalo.glb',g2=>{const a=g2.scene,ab=new THREE.Box3().setFromObject(a),as=ab.getSize(new THREE.Vector3()),ac=ab.getCenter(new THREE.Vector3()),ak=2.75/Math.max(.01,as.z);
   a.scale.setScalar(ak);a.position.set(-ac.x*ak,-ab.min.y*ak+.62,-ac.z*ak);const aw=new THREE.Group();aw.rotation.y=Math.PI;aw.position.z=-.45;aw.add(a); // coelheira no pescoço, varais para trás até a carroça
   a.traverse(o=>{if(o.isMesh){o.castShadow=!terrainLowSpec;o.receiveShadow=true;}});horse.add(aw);},undefined,()=>{});
  const parent=road.mule.parent;if(parent){road.mule.visible=false;road.horse=horse;horse.position.copy(road.mule.position);horse.rotation.y=road.mule.rotation.y;parent.add(horse);}},undefined,e=>console.warn('Cavalo.glb não carregou; mantendo a mula procedural.',e));
 // Lona solta (antes) / presa (depois) sobre os sacos vazios da traseira.
 // Lona solta caída atrás da carroça (antes de prender); depois de presa ela some sob a cobertura do próprio modelo.
 {const tg=new THREE.PlaneGeometry(1.7,1.2,6,4),tp=tg.attributes.position;for(let i=0;i<tp.count;i++)tp.setZ(i,Math.sin(tp.getX(i)*3.1)*.08+Math.cos(tp.getY(i)*4.3)*.06);tg.computeVertexNormals();
  road.tarp=new THREE.Mesh(tg,new THREE.MeshStandardMaterial({color:0x8c7d5e,roughness:1,side:THREE.DoubleSide}));road.tarp.position.set(.4,.06,-3.1);road.tarp.rotation.set(-Math.PI/2+.05,0,.5);road.tarp.visible=roadStage===ROAD.meet;road.cart.add(road.tarp);}
 // Lanterna de Teren: única luz extra do trecho, acesa só à noite na estrada.
 road.lamp=new THREE.PointLight(0xffb36a,0,15,1.6);road.lamp.position.set(-.55,2.3,1.9);road.cart.add(road.lamp);
 {const lm=new THREE.Mesh(new THREE.SphereGeometry(.11,8,6),new THREE.MeshBasicMaterial({color:0xffc27a,toneMapped:false}));lm.position.copy(road.lamp.position);road.cart.add(lm);road.lampGlow=lm;}
 for(let i=0;i<3;i++){const sack=new THREE.Mesh(new THREE.SphereGeometry(.32,8,6),mat(0x9a8a68));sack.scale.set(1,.55,.8);sack.position.set(-.55+i*.55,1.62,-1.15+(i%2)*.4);road.cart.add(sack);}
 const L=new GLTFLoader();L.load('./Carroça.glb',gltf=>{const m=gltf.scene,b=new THREE.Box3().setFromObject(m),s=b.getSize(new THREE.Vector3()),c=b.getCenter(new THREE.Vector3()),k=4.4/Math.max(.01,s.x);
  m.scale.setScalar(k);m.position.set(-c.x*k,-b.min.y*k,-c.z*k);const wrap=new THREE.Group();wrap.rotation.y=Math.PI/2;wrap.add(m);road.cart.add(wrap);road.cartModel=wrap;
  m.traverse(o=>{if(o.isMesh){o.castShadow=!terrainLowSpec;o.receiveShadow=true;}});},undefined,e=>console.warn('Carroça.glb não carregou para a estrada.',e));
 /* MOD 317 — Teren é o morador masculino Meshy (NPC_Masculino_Animado_Otimizado_1K.glb + Cabelo-otimizado.glb preso ao
    osso da cabeça), nunca o Npc.glb. Fica SENTADO no banco do cocheiro (socket medido no modelo da carroça), segurando
    as rédeas; o clipe Alert segue no tronco/cabeça (respira e olha a estrada) e a pose sentada é aplicada por cima. */
 npcFactory.create({sex:'man',role:'idle',x:0,z:0,hairToHead:true}).then(n=>{if(road.teren)return;const alert=(n.animations||[]).find(c=>/^alert$/i.test(c.name));
  if(n.mixer){n.mixer.stopAllAction();if(alert){const a=n.mixer.clipAction(alert);a.play();a.setEffectiveTimeScale(.45);n.action=a;}}
  n.holder.name='Teren-cocheiro';n.holder.traverse(o=>{if(o.isMesh){o.castShadow=!terrainLowSpec;o.material=o.material.clone();if(o.name!=='CabeloMeshy'&&o.material.color)o.material.color.multiply(new THREE.Color(0xb4a48a));}});
  road.teren={holder:n.holder,mixer:n.mixer||new THREE.AnimationMixer(n.holder),action:n.action,seat:createSeatPose(THREE,n.model,{reins:true})};road.group.add(n.holder);placeRoadCart(road.s,true);
 }).catch(e=>console.warn('Teren (NPC Masculino) não carregou',e));
 road.obstacle={x:0,z:0,radius:1.9,height:3,base:0};rockObstacles.push(road.obstacle);
 road.arrived=roadStage!==ROAD.meet||road.met;placeRoadCart(cartRestS(roadStage,road.arrived),true);
}
function placeRoadCart(s,snap){
 road.s=s;const p=roadAt(s),y=groundHeightAt(p.x,p.z);
 const prevYaw=road.yaw;if(road.yaw===null||snap)road.yaw=p.yaw;else{let d=p.yaw-road.yaw;d=Math.atan2(Math.sin(d),Math.cos(d));road.yaw+=d*.08;}road.yawRate=prevYaw===null||snap?0:Math.atan2(Math.sin(road.yaw-prevYaw),Math.cos(road.yaw-prevYaw))*60;
 const fx=Math.sin(road.yaw),fz=Math.cos(road.yaw),ahead=groundHeightAt(p.x+fx*1.6,p.z+fz*1.6),behind=groundHeightAt(p.x-fx*1.6,p.z-fz*1.6);
 road.cart.position.set(p.x,y,p.z);road.cart.rotation.set(0,road.yaw,0);road.cart.rotateX(-Math.atan2(ahead-behind,3.2));
 const mx=p.x+fx*3.35,mz=p.z+fz*3.35;road.mule.position.set(mx,groundHeightAt(mx,mz),mz);road.mule.rotation.y=road.yaw;if(road.horse){road.horse.position.copy(road.mule.position);road.horse.rotation.y=road.yaw;}
 if(road.teren){cartSocketWorld('driver',_seatW);road.teren.holder.position.copy(_seatW);road.teren.holder.rotation.y=road.yaw;}
 road.obstacle.x=p.x;road.obstacle.z=p.z;road.obstacle.base=y;
 storyAnchors.cart={x:p.x,z:p.z,y:y,yaw:road.yaw};
 const T=road.teren?road.teren.holder.position:{x:mx,z:mz};storyAnchors.teren={x:T.x,z:T.z,yaw:road.yaw};
}
/* MOD 317 — sockets locais medidos por raycast no Carroça.glb (frente = +z): banco do cocheiro na plataforma da frente
   (assento a 1,32 m), assoalho da cabine a 1,16 m e banco traseiro a 1,64 m. O herói senta no banco traseiro olhando
   para a frente; Aethraziel (2,8 m de altura) senta no assoalho de frente para ele, joelhos dobrados — cabe sob a lona
   (teto a ~2,9 m) sem atravessá-la. Porta lateral direita com degrau. */
const CART_SOCKETS={driver:{x:0,y:1.32,z:1.5,yaw:0},hero:{x:.04,y:1.64,z:-1.45,yaw:0},guide:{x:0,y:1.16,z:.42,yaw:Math.PI},door:{x:1.75,y:0,z:-.3},step:{x:1.05,y:1.16,z:-.3}};
const _seatW=new THREE.Vector3();
function cartSocketWorld(key,out){const S=CART_SOCKETS[key];out.set(S.x,S.y,S.z);road.cart.updateMatrixWorld(true);return road.cart.localToWorld(out);}
var heroSeat=null,guideSeat=null,seatedNow=false;
function seatPassengers(){
 road.passengers=true;seatedNow=true;player.visible=true;guide.visible=true;setGuideWings(false,true);
 if(!heroSeat&&model)heroSeat=createSeatPose(THREE,model,{reins:false});if(!guideSeat&&guideModel)guideSeat=createSeatPose(THREE,guideModel,{reins:false,floor:true,legSpread:.18});
 playerYaw=road.yaw+CART_SOCKETS.hero.yaw;player.rotation.y=playerYaw;guide.rotation.y=road.yaw+CART_SOCKETS.guide.yaw;
 placeSeated();
}
/** Mantém cada passageiro no socket (curvas, inclinação e solavancos da carroça) e apoia o quadril no assento. */
function placeSeated(){
 if(!seatedNow||!road.cart)return;
 cartSocketWorld('hero',_seatW);player.position.copy(_seatW);playerYaw=road.yaw+CART_SOCKETS.hero.yaw;player.rotation.y=playerYaw;
 cartSocketWorld('guide',_seatW);guide.position.copy(_seatW);guide.rotation.y=road.yaw+CART_SOCKETS.guide.yaw;
}
const _seatF=new THREE.Vector3();
function applySeating(dt){
 const t=performance.now()*.001,bump=road.ride&&road.speed>.2?Math.sin(t*9.5)*.012+Math.sin(t*5.3)*.008:0,lean=road.ride?THREE.MathUtils.clamp((road.yawRate||0)*.6,-.12,.12):0;
 if(road.teren&&road.teren.seat&&road.group&&road.group.visible){const T=road.teren;_seatF.set(Math.sin(road.yaw),0,Math.cos(road.yaw));T.seat.apply({forward:_seatF,lean,t});cartSocketWorld('driver',_seatW);T.holder.position.y=_seatW.y+.07-T.seat.hipHeight(T.holder)+bump;}
 if(!seatedNow)return;placeSeated();
 if(heroSeat&&model){_seatF.set(Math.sin(playerYaw),0,Math.cos(playerYaw));heroSeat.apply({forward:_seatF,lean:-lean,t});const hh=heroSeat.hipHeight(player);player.position.y+=-hh+.08+bump;}
 if(guideSeat&&guideModel){const gy=guide.rotation.y;_seatF.set(Math.sin(gy),0,Math.cos(gy));guideSeat.apply({forward:_seatF,lean,t});const gh=guideSeat.hipHeight(guide);guide.position.y+=-gh+.1+bump;}
}
function unseatPassengers(){seatedNow=false;}
/** MOD 317 — câmera DENTRO da cabine: por cima do ombro de um passageiro para o rosto do outro (nada de câmera olhando
    o vazio lá fora durante a conversa). Tremor discreto da estrada; no cochilo, aproximação lenta do rosto do herói. */
const _ic=new THREE.Vector3(),_il=new THREE.Vector3();
function cartInteriorCam(look,dt,doze,u=0){
 const L=look==='hero';const t=performance.now()*.001,sh=road.ride?Math.sin(t*11)*.006:0;
 // posições locais (frente = +z): ombro do anjo olhando o herói, ou ombro do herói olhando o anjo
 // alvos medidos no jogo com os dois sentados (cabeça do herói ~(0,2,24,-1,3); do anjo no assoalho ~(0,2,0,0,14)).
 // Não usa a posição do osso aqui: esta câmera roda ANTES de applySeating no quadro, e o osso ainda estaria na pose em pé.
 if(L){_ic.set(-.46,2.36+sh,.36-(doze?u*.3:0));_il.set(.04,2.2,-1.3);}
 else{_ic.set(.44,2.42+sh,-1.18);_il.set(0,1.98,.14);}
 road.cart.updateMatrixWorld(true);road.cart.localToWorld(_ic);road.cart.localToWorld(_il);
 // nunca atrás de tábua: raio do rosto olhado até a câmera contra a malha da carroça; a câmera para antes da parede
 if(road.cartModel){_icD.subVectors(_ic,_il);const dist=_icD.length();if(dist>.05){_icD.multiplyScalar(1/dist);_icRay.set(_il,_icD);_icRay.far=dist+.15;const hit=_icRay.intersectObject(road.cartModel,true)[0];if(hit)_ic.copy(_il).addScaledVector(_icD,Math.max(.32,hit.distance-.14));}}
 // entrada no interior e troca de quem fala são cortes secos (a câmera nunca desliza através das tábuas ou dos passageiros)
 const now=performance.now();if(now-cartInteriorCam.last>400||cartInteriorCam.look!==look)cineCut=true;cartInteriorCam.last=now;cartInteriorCam.look=look;
 if(camera.near!==.08){camera.near=.08;camera.updateProjectionMatrix();}
 storyCam(_ic.x,_ic.y,_ic.z,_il.x,_il.y,_il.z,4,dt,true);
}
cartInteriorCam.last=0;const _icRay=new THREE.Raycaster(),_icD=new THREE.Vector3();
/** MOD 317 — embarque sem teleporte: o herói caminha até a porta, sobe o degrau, entra e senta; Aethraziel entra logo
    depois e senta no assoalho. Tudo por trajetória curta em tempo de cena (pular a cena só assenta os dois). */
/** MOD 317 — cenas longas só podem ser puladas depois da primeira exibição (memória por save neste aparelho). */
const STORY_SEEN_STORE='seven-sins-3d-cenas-vistas';
function storySeen(id){try{return (JSON.parse(localStorage.getItem(STORY_SEEN_STORE)||'[]')).includes(id);}catch(_){return false;}}
function markStorySeen(id){try{const a=JSON.parse(localStorage.getItem(STORY_SEEN_STORE)||'[]');if(!a.includes(id)){a.push(id);localStorage.setItem(STORY_SEEN_STORE,JSON.stringify(a));}}catch(_){}}
function boardCart(){
 if(cineSkipping){seatPassengers();return;}
 const door=cartSocketWorld('door',new THREE.Vector3()),step=cartSocketWorld('step',new THREE.Vector3()),seat=cartSocketWorld('hero',new THREE.Vector3());
 const gseat=cartSocketWorld('guide',new THREE.Vector3()),from=player.position.clone(),gfrom=guide.position.clone();if(actions.walk)play('walk',.2);
 const T=2.6;storyFx.push({t:0,tick:(t)=>{const k=Math.min(1,t/T);let p;
  if(k<.55){const u=k/.55;p=from.clone().lerp(door,u*u*(3-2*u));p.y=groundHeightAt(p.x,p.z);faceTo(player,door);}
  else if(k<.72){const u=(k-.55)/.17;p=door.clone().lerp(step,u);p.y=THREE.MathUtils.lerp(groundHeightAt(door.x,door.z),step.y,Math.sin(u*Math.PI/2));faceTo(player,seat);}
  else{const u=(k-.72)/.28;p=step.clone().lerp(seat,u);p.y=THREE.MathUtils.lerp(step.y,seat.y,u);}
  player.position.copy(p);
  const gk=Math.max(0,Math.min(1,(t-.6)/T));const gp=gk<.6?gfrom.clone().lerp(door,gk/.6):door.clone().lerp(gseat,(gk-.6)/.4);if(gk<.6)gp.y=groundHeightAt(gp.x,gp.z);else gp.y=THREE.MathUtils.lerp(groundHeightAt(door.x,door.z),gseat.y,(gk-.6)/.4);guide.position.copy(gp);faceTo(guide,gk<.6?door:gseat);
  if(t>=T+.6){if(actions.idle)play('idle',.25);seatPassengers();return false;}return true;}});
}
function stepOutOfCart(side){
 const c=road.cart.position,fx=Math.sin(road.yaw),fz=Math.cos(road.yaw),rx=fz*side,rz=-fx*side;road.passengers=false;unseatPassengers();
 const x=c.x+rx*2.4,z=c.z+rz*2.4;player.position.set(x,groundHeightAt(x,z),z);player.visible=true;
 const gx=c.x+rx*2.6-fx*1.6,gz=c.z+rz*2.6-fz*1.6;guide.position.set(gx,groundHeightAt(gx,gz),gz);guide.visible=true;
 checkpointX=x;checkpointZ=z;
}
function updateRoad(dt){
 const need=questStep===1&&act1Sub===0&&roadStage<ROAD.done||road.leaving>0;
 if(!need){if(road.group&&!road.leaving){road.group.visible=false;road.obstacle.radius=0;}return;}
 ensureRoadProps();road.group.visible=true;road.obstacle.radius=road.leaving||cineActive?0:1.9; // a câmera das cenas não colide com a carroça
 if(road.hideBandits&&pack&&pack.clones)for(const cl of pack.clones)if(cl)cl.holder.visible=false;
 if(road.approach&&!road.ride){/* MOD 317: a carroça desce a garganta e chega ao prado; o som vem antes da imagem */const dS=RIDE.start-road.s,sp=Math.min(6.2,1+dS*.14);placeRoadCart(Math.min(RIDE.start,road.s+sp*dt));const dist=Math.hypot(road.cart.position.x-player.position.x,road.cart.position.z-player.position.z);worldAudio.setCart&&worldAudio.setCart(Math.max(.15,1-dist/90));road.legT+=dt*sp*2.6;if(road.horseAction)road.horseAction.timeScale=Math.min(1.6,sp*.3);if(dS<.05){road.approach=false;road.arrived=true;worldAudio.setCart&&worldAudio.setCart(0);worldAudio.land();}}
 if(road.ride){const target=road.rideTo;road.speed=THREE.MathUtils.damp(road.speed,road.rideSpeed||ROAD.rideSpeed,2.2,dt);let s=road.s+road.speed*dt;if(target!==undefined&&s>=target){s=target;road.ride=false;road.speed=0;}placeRoadCart(s);if(road.passengers)seatPassengers();
  if(road.dawnK>=0){const k=(road.s-RIDE.ambush)/Math.max(1,RIDE.end-RIDE.ambush);setGameHour(dawnHourAt(k));}}
 const moving=road.ride&&road.speed>.2;road.legT+=dt*(moving?road.speed*2.6:0);
 for(const l of road.legs)l.pivot.rotation.x=moving?Math.sin(road.legT+l.ph)*.5:0;
 if(road.horseMixer){if(road.horseAction)road.horseAction.timeScale=moving?Math.min(1.6,road.speed*.3):0;road.horseMixer.update(dt);}
 if(road.teren){road.teren.mixer.update(dt);} // MOD 317: sentado; o clipe Alert segue lento (respiração e olhar)
 if(road.cartModel&&moving)road.cartModel.position.y=Math.abs(Math.sin(road.legT*.9))*.035;
 if(road.lamp){const n=dayNightState.t;road.lamp.intensity=n*2.4;road.lampGlow.visible=n>.2;}
 if(road.leaving>0){road.leaving-=dt;if(road.leaving<=0){road.group.visible=false;road.leaving=0;}}
 for(let i=road.bandits.length-1;i>=0;i--){const bd=road.bandits[i],h=bd.holder;bd.mixer.update(dt);if(!bd.go)continue;const dx=bd.go.x-h.position.x,dz=bd.go.z-h.position.z,d=Math.hypot(dx,dz);
  if(d>.35){h.position.x+=dx/d*dt*2.6;h.position.z+=dz/d*dt*2.6;h.rotation.y=Math.atan2(dx,dz);h.position.y=groundHeightAt(h.position.x,h.position.z);}else if(bd.leave){scene.remove(h);road.bandits.splice(i,1);}else bd.go=null;}
}
function startRoadRide(to,speed,riders=true){road.ride=true;road.rideTo=to;road.rideSpeed=speed||ROAD.rideSpeed;road.passengers=riders;if(riders)seatPassengers();}
function clearRoadBandits(){for(const b of road.bandits)scene.remove(b.holder);road.bandits.length=0;}
function spawnSurrendered(){
 return npcBase().then(b=>{clearRoadBandits();const c=road.cart.position;
  ROAD_BANDITS.forEach((s,i)=>{const v=makeTownsfolk(b,[0x8a7a6a,0x6a5a4a,0x9a8070,0x5a6a5a,0x7a6050][i%5],'Alert',{bandit:true,leader:i===0});const x=(s.x+c.x)/2+(i-2)*.9,z=(s.z+c.z)/2+1.2;v.holder.position.set(x,groundHeightAt(x,z),z);v.holder.rotation.y=Math.atan2(player.position.x-x,player.position.z-z);if(v.action)v.action.timeScale=.6;road.bandits.push(v);});
  const f=road.bandits[0].holder.position;storyAnchors.bandit={x:f.x,z:f.z,yaw:road.bandits[0].holder.rotation.y};});
}
function roadStoryDo(id){
 switch(id){
  case 'carroca-frear':ensureRoadProps();road.approach=false;road.arrived=true;placeRoadCart(RIDE.start,true);worldAudio.setCart&&worldAudio.setCart(0);worldAudio.land();return true;
  case 'anjo-recolhe-asas':foldGuideWings();return true;
  case 'carroca-ouvida':ensureRoadProps();if(!road.arrived)road.approach=true;return true;
  case 'lona-presa':if(road.tarp)road.tarp.visible=false;worldAudio.whoosh();return true;
  case 'embarcar':boardCart();return true;
  case 'tres-horas':storyTitle('3 HORAS DEPOIS','');return true;
  case 'viagem-partir':if(!seatedNow)seatPassengers();startRoadRide(RIDE.ambush,ROAD.rideSpeed);worldAudio.setCart&&worldAudio.setCart(1);return true;
  case 'piscadas':setCineFade(.75,.6,false);setTimeout(()=>setCineFade(0,.5,false),700);setTimeout(()=>setCineFade(.85,.7,false),1600);setTimeout(()=>setCineFade(.2,.6,false),2350);return true;
  case 'dormir':setCineFade(1,.9,false);worldAudio.setCart&&worldAudio.setCart(0);return true;
  case 'acordar':{road.ride=false;road.speed=0;placeRoadCart(RIDE.ambush,true);seatPassengers();setGameHour(1.6);setCineFade(0,1.6,false);const lids=cineEl('cine-lids');if(lids&&!cineSkipping){lids.className='on';void lids.offsetWidth;lids.className='on open';setTimeout(()=>{lids.className='';},3300);}return true;}
  case 'bandidos-cercam':{const c=road.cart.position;storyAnchors.bandit={x:ROAD_BANDITS[0].x,z:ROAD_BANDITS[0].z,yaw:Math.atan2(c.x-ROAD_BANDITS[0].x,c.z-ROAD_BANDITS[0].z)};road.hideBandits=false;if(pack&&pack.clones)for(const cl of pack.clones)if(cl)cl.holder.visible=true;worldAudio.block();return true;}
  case 'descer-carroca':stepOutOfCart(1);faceTo(player,ROAD_BANDITS[0]);return true;
  case 'bandidos-rendidos':return true;
  case 'bandidos-partem':{const c=road.cart.position;road.bandits.forEach((b,i)=>{b.go={x:c.x+(i-1.5)*7,z:c.z-14-i*2};b.leave=true;});walkBanditsAway();return true;}
  case 'bandidos-reparam':{const c=road.cart.position;road.bandits.forEach((b,i)=>{b.go={x:c.x+(i%2?1.2:-1.2),z:c.z+(i<2?1.4:-1.4)};});setTimeout(()=>{for(const b of road.bandits){b.go={x:c.x+(Math.random()-.5)*16,z:c.z-16};b.leave=true;}walkBanditsAway();},4200);return true;}
  case 'viagem-retomar':placeRoadCart(road.s,true);startRoadRide(RIDE.revealAt-30,ROAD.rideSpeed);road.dawnK=0;worldAudio.setCart&&worldAudio.setCart(1);return true;
  case 'timelapse-amanhecer':return true;
  case 'pular-madrugada':{
   // Ao pular a cena, as ações restantes rodam na hora (carroca-parar/descer-chegada/finishRoad): nada pode ficar agendado.
   const jump=()=>{if(roadStage>=ROAD.done||!road.passengers)return;placeRoadCart(RIDE.end-22,true);seatPassengers();startRoadRide(RIDE.end,3.6);setCineFade(0,1.2,false);storyTitle('AO AMANHECER','Eldória');};
   if(cineSkipping){placeRoadCart(RIDE.end-22,true);return true;}
   setCineFade(1,.5,false);setTimeout(jump,560);return true;}
  case 'carroca-parar':road.ride=false;road.speed=0;placeRoadCart(RIDE.end,true);road.dawnK=-1;setGameHour(6.9);worldAudio.setCart&&worldAudio.setCart(0);return true;
  case 'descer-chegada':stepOutOfCart(-1);faceTo(player,VILLAGE_CENTER);return true;
 }
 return false;
}
function walkBanditsAway(){npcBase().then(b=>{const clip=b.clips.find(k=>k.name==='Walking');if(!clip)return;for(const bd of road.bandits){bd.mixer.stopAllAction();bd.mixer.clipAction(clip).play();}}).catch(()=>{});}
function roadTalkLabel(){
 if(cineActive||!(questStep===1&&act1Sub===0)||roadStage>=ROAD.done||!road.group||pack||enemy.visible)return '';
 const c=road.cart.position,d=Math.hypot(c.x-player.position.x,c.z-player.position.z);if(d>ROAD.cartReach+2)return '';
 if(roadStage===ROAD.meet&&road.met)return 'PRENDER A LONA';
 if(roadStage===ROAD.boarded||roadStage===ROAD.freed)return 'SUBIR NA CARROÇA';
 return '';
}
function roadInteract(){
 const label=roadTalkLabel();if(!label)return false;act1Lock=true;
 if(label==='PRENDER A LONA'){playStory('lona',tarpScene(),{focus:'teren',done:()=>{act1Lock=false;setRoadStage(ROAD.boarded);status.textContent='Suba na carroça de Teren.';}});return true;}
 if(roadStage===ROAD.boarded){
  road.hideBandits=true;startPack({rig:'bandit',profile:'bandit1',hp:ROAD.banditHp,spots:ROAD_BANDITS,hold:true,intro:'Bandidos famintos fecham a estrada.',onDone:roadBanditsDown});
  if(pack&&pack.clones)for(const cl of pack.clones)if(cl)cl.holder.visible=false;
  const seenRide=storySeen('estrada-viagem');playStory('estrada-viagem',rideDozeScene(),{focus:'cart',skippable:seenRide,done:()=>{markStorySeen('estrada-viagem');
   for(const cl of (pack&&pack.clones)||[])if(cl){cl.holder.visible=true;cl.holder.rotation.y=Math.atan2(road.cart.position.x-cl.holder.position.x,road.cart.position.z-cl.holder.position.z);}
   playStory('emboscada',ambushScene(),{focus:'bandit',done:()=>{act1Lock=false;releasePack();checkpointX=player.position.x;checkpointZ=player.position.z;status.textContent='Desarme os bandidos sem matar ninguém.';}});}});
  return true;}
 playStory('amanhecer',dawnRideScene(),{focus:'teren',done:()=>{act1Lock=false;finishRoad();}});return true;
}
function roadBanditsDown(){
 act1Lock=true;spawnSurrendered().then(()=>{playStory('bandidos-fome',hungerScene(),{focus:'bandit',done:()=>{
  {const card=cineEl('choice-card');if(card&&choiceMode==='bandidos')card.hidden=true;}
  playStory('bandidos-escolha',choiceScene(!!road.choice),{focus:'teren',done:()=>{act1Lock=false;setRoadStage(ROAD.freed);status.textContent='Volte à carroça de Teren.';}});}});},()=>{act1Lock=false;setRoadStage(ROAD.freed);});
}
/** MOD 317 — na estrada do prólogo (do despertar até a chegada) Aethraziel/Vaelthar anda ao lado do herói: some só
    dentro da carroça (lá ele está sentado) e para de seguir durante a luta (fica junto da carroça, olhando). */
var guideCompanion=false;
function roadCompanion(dt){
 guideCompanion=false;
 if(!(questStep===1&&act1Sub===0&&roadStage<ROAD.done&&awakeningSeen)||voidMode)return;
 if(seatedNow||road.passengers){guide.visible=true;return;}
 if(cineActive)return;
 guide.visible=true;const P=player.position,G=guide.position;
 if(pack&&pack.active){faceTo(guide,P);return;}
 const fx=Math.sin(playerYaw),fz=Math.cos(playerYaw),tx=P.x+fz*2.3-fx*1.1,tz=P.z-fx*2.3-fz*1.1;
 const dp=Math.hypot(P.x-G.x,P.z-G.z);
 if(dp>28){G.set(tx,groundHeightAt(tx,tz),tz);faceTo(guide,P);return;}
 const dx=tx-G.x,dz=tz-G.z,d=Math.hypot(dx,dz);
 if(d<.9||dp<2.2){guideMoveSpeed=0;if(dp<6)faceTo(guide,P);return;}
 const sp=Math.min(5.4,1.5+d*.9),st=Math.min(d,dt*sp),a0=Math.atan2(dx,dz);
 for(const da of [0,.4,-.4,.8,-.8]){const a=a0+da,nx=G.x+Math.sin(a)*st,nz=G.z+Math.cos(a)*st;if(!blockedAt(nx,nz)){G.x=nx;G.z=nz;G.y=groundHeightAt(nx,nz);guide.rotation.y=a;guideMoveSpeed=dt>0?st/dt:0;guideCompanion=true;return;}}
}
function finishRoad(){
 road.ride=false;road.speed=0;stepOutOfCart(-1);road.passengers=false;setCineFade(0,.4,false);setRoadStage(ROAD.done);
 status.textContent='Atravesse a ponte até Eldória e fale com um vendedor.';road.leaving=7;road.obstacle.radius=0;startRoadRide(RIDE.total,2.4,false);
 act1Toast('ELDÓRIA');
}
function updateRoadQuest(px,pz,near,mark){
 ensureRoadProps();if(!rigLoads.bandit)loadRig('bandit').catch(()=>{});
 if(roadStage===ROAD.meet&&!road.met){
  // MOD 317 — antes de qualquer humano: o herói pergunta das asas e Aethraziel as recolhe; então a carroça é ouvida.
  // save recarregado antes das asas: arma só com o herói já no prado (o save reposiciona o herói depois do 1º quadro)
  if(!guideWingsHidden&&awakeningSeen&&!act1Busy()&&Math.hypot(px-FALL_SPOT.x,pz-FALL_SPOT.z)<90&&(prologueAwake||(prologueAwake={t:performance.now(),x:px,z:pz,lazy:true}))&&(performance.now()-prologueAwake.t>4500||(!prologueAwake.lazy&&Math.hypot(px-prologueAwake.x,pz-prologueAwake.z)>5))){act1Lock=true;{const G=guide.position;if(Math.hypot(G.x-px,G.z-pz)>7){const fx=Math.sin(playerYaw),fz=Math.cos(playerYaw),gx=px+fz*2.2+fx*1.4,gz=pz-fx*2.2+fz*1.4;G.set(gx,groundHeightAt(gx,gz),gz);}guide.visible=true;faceTo(guide,player.position);}faceTo(player,guide.position);playStory('asas',wingsScene(),{focus:'guide',face:'guide',done:()=>{act1Lock=false;status.textContent='Rodas na estrada: vá até ela.';}});return;}
  if(guideWingsHidden&&!road.arrived&&!road.approach)road.approach=true; // save recarregado: a carroça volta a descer
  if(!road.arrived){mark(TEREN_STOP);return;}
  mark(road.cart.position);if(!act1Busy()&&near(road.cart.position,ROAD.meetRadius)){road.met=true;act1Lock=true;faceTo(player,road.cart.position);playStory('teren',terenMeetScene(),{focus:'teren',face:'teren',done:()=>{act1Lock=false;status.textContent='Ajude Teren a prender a lona da carroça.';}});}return;}
 mark(road.cart.position);
}

