 W.fireballs=[];for(let i=0;i<10;i++){const f=glowSprite(0xff5a10,.95,6);f.visible=false;scene.add(f);W.fireballs.push({s:f,t:Math.random()*2.5,from:new THREE.Vector3(),to:new THREE.Vector3()});}
