  const base2=new THREE.Mesh(new THREE.CylinderGeometry(.45,.6,.3,8),clay);base2.position.y=.15;fig.add(base2);
  marketObstacles.push({x:p.x,z:p.z,shape:'circle',radius:.85,height:.8});
