 if(LUNAR_TEST&&!lunarTestFired&&dimBattle&&dimBattle.active&&isVeraxionProfile(encounterProfile)&&lunarCosmosReady()&&(lunarTestWait+=dt)>2.5&&startLunarUlt()){lunarTestFired=true;return;} /* teste: espera a câmera da luta assentar */
