  if(COSMIC_TEST&&!cosmicTestFired&&dimBattle&&dimBattle.active&&isVorgazhekProfile(encounterProfile)&&enemyHP<enemyMaxHP+1){cosmicTestFired=true;startCosmicUlt();return;}
