 const y=fxGy(x,z),pts=[];let px=x,pz=z;for(let k=0;k<=12;k++){pts.push(new THREE.Vector3(px,y+h-k/12*h,pz));px=x+(Math.random()-.5)*1.6*(1-k/12);pz=z+(Math.random()-.5)*1.6*(1-k/12);}pts[12].set(x,y,z);
