/** MOD 302: modo do golpe (chão, corrida, saída do dash, aéreo, mergulho), alvo escolhido e aproximação travada nele. */
function protaAttack(){
 const air=!grounded,high=air&&player.position.y-terrainHeightAt(player.position.x,player.position.z)>1.1;
 const mode=air?((verticalVelocity<-.6&&high)||prota302.airAttacks>=2?'plunge':'air'):(dashRemaining>0||prota302.clock<prota302.attackAfterDash)?'dash':isSprinting()&&Math.hypot(moveVX,moveVZ)>PROTA_LOCO.walk*1.3?'run':'ground';
 if(rites.busy){rites.attack(equippedSword,{mode});return;}// só enfileira (o buffer do golpe atual decide)
 const pick=protaPick();
 if(dashRemaining>0){dashRemaining=0;protaDashEnd();}
 const ok=rites.attack(equippedSword,{damage:Math.round(SWORDS[equippedSword].damage*(1+statsForLevel(playerLevel()).damageBonus)*scrollMul()),yaw:mode==='dash'&&!pick.target?Math.atan2(dashDirX,dashDirZ):pick.yaw,target:pick.target||riteTarget(),mode});
 if(ok&&rites.active)rites.active.lockId=pick.target?pick.target.id:null;
}
function castSwordRite(){
 if(!riteReady()||!grounded||dashRemaining>0||(activeAction===actions.hit&&performance.now()<actionUntil)||siege.active||whiteLease.locked){status.textContent='Conclua a ação atual antes de usar o rito.';return;}
 const result=rites.cast(equippedSword,{mana:playerMana,owned:equippedSword==='prota'||ownedItems.has(equippedSword),damage:Math.round(SWORDS[equippedSword].damage*(1+statsForLevel(playerLevel()).damageBonus)*scrollMul()),yaw:riteFacing(),from:player.position,target:riteTarget()});
 if(result.ok){playerMana-=result.cost;const t=riteTarget();status.textContent=SWORD_RITES[equippedSword].name+(equippedSword==='aurora'&&t.alive&&Math.hypot(t.x-player.position.x,t.z-player.position.z)>18?' · Alvo fora do alcance (18 m). Mire para lançar.':'');}else status.textContent=result.reason;
 updateRiteHud();
}
function updateRites(dt){
 if(combatLabRequested&&riteReady()&&!document.getElementById('combat-lab244'))installCombatLab();
 if(swordTrainingRequested&&!swordTrainingRequestedStarted&&model&&mixer&&player.userData.ready&&(quantumShowcaseRequested||riteReady())){swordTrainingRequestedStarted=true;startSwordTraining().catch(e=>{console.error(e);swordTrainingRequestedStarted=false;status.textContent='Falha ao iniciar treino: '+e.message;});}
 const valid=playerHP>0&&!cineActive&&!dialogueOpen&&!namePromptOpen&&!awakeningActive&&!portalPull&&!whiteLease.locked&&(!(rites.busy||rites.waves.length)||riteContext===siegeContext());
 rites.update(dt,{valid,grounded,moving:Math.hypot(moveVX,moveVZ)>.12,sword:equippedSword,from:player.position,target:riteTarget(),yaw:riteFacing(),others:protaOthers()});
 riteVFX.update(dt,graphics3DIsLow()?'low':graphics3DMode==='max'?'high':'medium',cameraDistance<1.05&&!riteCinematicView);protaVFX.update(dt,camera,graphics3DIsLow()?'low':graphics3DMode==='max'?'high':'medium');updateRiteHud();
 updateCombat314(dt);
}
/* MOD 315 — relógio de combate, escudos, cortes e HUD de dash/escudo (mesmo caminho no jogo e no combatStep). */
function updateCombat314(dt){
 combatClock+=dt;heroShield.update(combatClock);
 shieldVFX.sync('hero',heroShield,player.position,playerReferenceHeight||1.85,combatClock,'celeste',dt);
 slashVFX.update(dt,camera,graphics3DIsLow()?'low':graphics3DMode==='max'?'high':'medium');updateCombatHud();
}
const dashButton=document.getElementById('dash'),shieldButton=document.getElementById('shield'),combatHudLast={d:-1,s:''};
function updateCombatHud(){
 const dl=heroMob.dashLeft(combatClock),dk=Math.round(dl*20);
 if(dashButton&&dk!==combatHudLast.d){combatHudLast.d=dk;dashButton.style.setProperty('--cd',String(dl/MOBILITY.dashCooldown));dashButton.classList.toggle('skill-cooling',dl>0);dashButton.setAttribute('aria-disabled',String(dl>0));
  let c=dashButton.querySelector('.skill-cost');if(!c){c=document.createElement('span');c.className='skill-cost';dashButton.appendChild(c);}c.textContent=dl>0?dl.toFixed(1):'';c.hidden=!(dl>0);}
 if(!shieldButton)return;
 const st=heroShield.state,left=st==='active'?heroShield.remaining(combatClock):heroShield.cooldownLeft(combatClock),key=st+':'+Math.ceil(left*10)+':'+Math.round(heroShield.damage*20);
 if(key===combatHudLast.s)return;combatHudLast.s=key;
 shieldButton.classList.toggle('on',st==='active');shieldButton.classList.toggle('skill-cooling',st==='cooldown');shieldButton.setAttribute('aria-disabled',String(st!=='ready'));
 shieldButton.style.setProperty('--cd',st==='cooldown'?String(left/heroShield.spec.cooldown):'0');shieldButton.style.setProperty('--hp',String(1-heroShield.damage));
 const c=shieldButton.querySelector('.skill-cost');if(c){c.textContent=st==='ready'?'':st==='active'?left.toFixed(1):Math.ceil(left)+'s';c.hidden=st==='ready';}
 shieldButton.setAttribute('aria-label','Escudo — '+(st==='ready'?'pronto':st==='active'?'ativo, '+left.toFixed(1)+' s, integridade '+Math.round((1-heroShield.damage)*100)+'%':'recarga '+Math.ceil(left)+' s'));
}
const riteButton=document.getElementById('sword-skill');
function updateRiteHud(){
 const def=SWORD_RITES[equippedSword];riteButton.hidden=!def;riteButton.classList.toggle('skill-locked',!def);if(!def)return;
 const cd=rites.cooldowns[equippedSword],label=riteButton.querySelector('.btn-label'),cost=riteButton.querySelector('.skill-cost');label.textContent=def.label;cost.textContent=cd>0?Math.ceil(cd)+'s':def.mana;riteButton.dataset.sword=equippedSword;riteButton.style.setProperty('--cd',String(cd/def.cooldown));riteButton.classList.toggle('skill-cooling',cd>0);riteButton.classList.toggle('skill-nomana',playerMana<def.mana);riteButton.setAttribute('aria-disabled',String(cd>0||rites.busy||playerMana<def.mana));riteButton.setAttribute('aria-label','Habilidade da espada: '+def.name+' — '+def.mana+' de mana — '+(cd>0?Math.ceil(cd)+' segundos':rites.busy?'em ação':playerMana<def.mana?'mana insuficiente':'pronta')+' (R)');riteButton.title=riteButton.getAttribute('aria-label');
}
bindInstantTap(riteButton,()=>action('sword-skill'));
async function startSwordTraining(boss=false){
 if(!testAllSkills||!model||!mixer||(!quantumShowcaseRequested&&!riteReady()))return;const epoch=++trainingEpoch;swordTrainingRequestedStarted=true;if(!quantumShowcaseRequested)await loadRig(boss?'bishop2':'enemy2');if(epoch!==trainingEpoch)return;rites.cancel('training');swordTraining=true;moveVX=moveVZ=verticalVelocity=dashRemaining=0;grounded=true;riteAudit.length=0;enemyHitFlash=0;setEnemyHitFlash(false);menuGate=false;gamePaused=false;awakeningActive=namePromptOpen=dialogueOpen=false;cineActive=false;portalPull=null;
 if(cineDirector.active)cineDirector.skip();clearPack();if(quantumShowcaseRequested){if(enemy1Rig)useRig('enemy1');}else useRig(boss?'bishop2':'enemy2');questStep=2;act1Sub=0;enemy.visible=false;revealEncounter(boss?'vorgazhek':'demon2',{x:-5,z:13},10000,'Treino de espadas · GOLPE encadeia o combo; R ativa o rito.');player.position.set(-5,terrainHeightAt(-5,16),16);playerYaw=Math.PI;player.rotation.y=playerYaw;playerHP=playerMaxHP;playerMana=100;rites.cooldowns.prota=rites.cooldowns.aurora=0;ownedItems.add('aurora');cameraYaw=0;cameraPitch=.22;cameraDistance=6;debugCameraOverride=null;camera.position.set(-5,terrainHeightAt(-5,16)+2.5,22);camera.lookAt(-5,terrainHeightAt(-5,16)+1.1,16);
 for(const id of ['start-gate','name-panel','dialog-panel','loading']){const el=document.getElementById(id);if(el){el.hidden=true;el.classList.add('hidden');}}
 if(quantumShowcaseRequested){
   for(const id of ['quantum','skill_x_rupture','skill_twin_portals','skill_judgment_dragon'])ownedItems.add(id);
   skillLoadout=['skill_x_rupture','skill_twin_portals','skill_judgment_dragon'];
   equipSword('quantum');refreshSkillUnlocks();
   status.textContent='TREINO MOD 236 · QUANTUM EQUIPADA · RUPTURA (1), PORTAIS (2), DRAGÃO (3) · ALVO DE 10.000 HP';
  }
  document.getElementById('sword-training').hidden=false;updateQuestHud();if(vfxLabRequested)setVfxLabMode(labMode);
}
if(testAllSkills){for(const id of Object.keys(WEAPON_STYLES))ownedItems.add(id);const panel=document.getElementById('sword-training');panel.hidden=false;bindInstantTap(document.getElementById('rite-training-start'),()=>startSwordTraining());bindInstantTap(document.getElementById('rite-training-swap'),()=>equipSword(Object.keys(WEAPON_STYLES)[(Object.keys(WEAPON_STYLES).indexOf(equippedSword)+1)%5]));}

